using DhaqaleysteApi.Options;
using Microsoft.Extensions.Options;

namespace DhaqaleysteApi.Services
{
    public enum MediaKind { Image, Video }

    public class FileStorageResult
    {
        public bool Success { get; init; }
        public string? Error { get; init; }
        public string Url { get; init; } = "";

        public static FileStorageResult Fail(string error) => new() { Error = error };
    }

    /// <summary>
    /// Stores uploaded media on local disk outside wwwroot. File names are generated by the server,
    /// the extension must be on an allow-list, and the file content must match that type.
    /// Swap this class for cloud storage later without changing the controllers.
    /// </summary>
    public class FileStorageService
    {
        public const string PublicPrefix = "/media";

        private static readonly Dictionary<string, MediaKind> AllowedExtensions = new(StringComparer.OrdinalIgnoreCase)
        {
            [".jpg"] = MediaKind.Image,
            [".jpeg"] = MediaKind.Image,
            [".png"] = MediaKind.Image,
            [".webp"] = MediaKind.Image,
            [".heic"] = MediaKind.Image,
            [".mp4"] = MediaKind.Video,
            [".m4v"] = MediaKind.Video,
            [".mov"] = MediaKind.Video,
            [".webm"] = MediaKind.Video
        };

        public static readonly IReadOnlyDictionary<string, string> ContentTypes = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            [".jpg"] = "image/jpeg",
            [".jpeg"] = "image/jpeg",
            [".png"] = "image/png",
            [".webp"] = "image/webp",
            [".heic"] = "image/heic",
            [".mp4"] = "video/mp4",
            [".m4v"] = "video/mp4",
            [".mov"] = "video/quicktime",
            [".webm"] = "video/webm"
        };

        private readonly StorageOptions _options;
        private readonly ILogger<FileStorageService> _logger;

        public string RootPath { get; }

        public FileStorageService(IOptions<StorageOptions> options, IWebHostEnvironment env, ILogger<FileStorageService> logger)
        {
            _options = options.Value;
            _logger = logger;
            RootPath = Path.GetFullPath(Path.Combine(env.ContentRootPath, _options.RootPath));
            Directory.CreateDirectory(Path.Combine(RootPath, "images"));
            Directory.CreateDirectory(Path.Combine(RootPath, "videos"));
        }

        public long MaxBytes(MediaKind kind) => kind == MediaKind.Image ? _options.MaxImageBytes : _options.MaxVideoBytes;

        public async Task<FileStorageResult> SaveAsync(IFormFile? file, MediaKind kind, CancellationToken ct)
        {
            if (file == null || file.Length == 0)
                return FileStorageResult.Fail("No file was uploaded.");

            if (file.Length > MaxBytes(kind))
                return FileStorageResult.Fail($"File is too large. Maximum is {MaxBytes(kind) / (1024 * 1024)} MB.");

            // Only the extension is taken from the client, and only if it is on the allow-list.
            var extension = Path.GetExtension(file.FileName);
            if (string.IsNullOrEmpty(extension) || !AllowedExtensions.TryGetValue(extension, out var actualKind) || actualKind != kind)
                return FileStorageResult.Fail(kind == MediaKind.Image
                    ? "Only JPG, PNG, WEBP or HEIC images are allowed."
                    : "Only MP4, MOV, M4V or WEBM videos are allowed.");

            await using (var probe = file.OpenReadStream())
            {
                var header = new byte[16];
                var read = await probe.ReadAtLeastAsync(header, header.Length, throwOnEndOfStream: false, ct);
                if (!SignatureMatches(extension, header.AsSpan(0, read)))
                    return FileStorageResult.Fail("The file content does not match its type.");
            }

            var folder = kind == MediaKind.Image ? "images" : "videos";
            var fileName = $"{Guid.NewGuid():N}{extension.ToLowerInvariant()}";
            var fullPath = Path.Combine(RootPath, folder, fileName);

            await using (var target = new FileStream(fullPath, FileMode.CreateNew, FileAccess.Write))
            await using (var source = file.OpenReadStream())
            {
                await source.CopyToAsync(target, ct);
            }

            _logger.LogInformation("Stored {Kind} upload {FileName} ({Bytes} bytes)", kind, fileName, file.Length);
            return new FileStorageResult { Success = true, Url = $"{PublicPrefix}/{folder}/{fileName}" };
        }

        /// <summary>True when the URL points at a file uploaded to our own media folder.</summary>
        public static bool IsOwnMediaPath(string? path, MediaKind kind)
        {
            if (string.IsNullOrWhiteSpace(path) || path.Contains("..") || path.Contains('\\') || path.Contains("//", StringComparison.Ordinal))
                return false;

            var folder = kind == MediaKind.Image ? "/images/" : "/videos/";
            return path.StartsWith(PublicPrefix + folder, StringComparison.Ordinal);
        }

        /// <summary>Deletes an uploaded file that is no longer used. Ignores anything outside our media folder.</summary>
        public void TryDelete(string? url)
        {
            if (string.IsNullOrWhiteSpace(url) || !url.StartsWith(PublicPrefix + "/", StringComparison.Ordinal) || url.Contains(".."))
                return;

            try
            {
                var relative = url[(PublicPrefix.Length + 1)..].Replace('/', Path.DirectorySeparatorChar);
                var fullPath = Path.GetFullPath(Path.Combine(RootPath, relative));
                if (fullPath.StartsWith(RootPath + Path.DirectorySeparatorChar, StringComparison.Ordinal) && File.Exists(fullPath))
                {
                    File.Delete(fullPath);
                    _logger.LogInformation("Deleted unused media {Url}", url);
                }
            }
            catch (Exception ex)
            {
                _logger.LogWarning(ex, "Could not delete media {Url}", url);
            }
        }

        private static bool SignatureMatches(string extension, ReadOnlySpan<byte> h)
        {
            switch (extension.ToLowerInvariant())
            {
                case ".jpg":
                case ".jpeg":
                    return h.Length >= 3 && h[0] == 0xFF && h[1] == 0xD8 && h[2] == 0xFF;
                case ".png":
                    return h.Length >= 8 && h[..8].SequenceEqual(new byte[] { 0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A });
                case ".webp":
                    return h.Length >= 12 && h[..4].SequenceEqual("RIFF"u8) && h[8..12].SequenceEqual("WEBP"u8);
                case ".webm":
                    return h.Length >= 4 && h[0] == 0x1A && h[1] == 0x45 && h[2] == 0xDF && h[3] == 0xA3;
                case ".heic":
                case ".mp4":
                case ".m4v":
                case ".mov":
                    // ISO base media file: bytes 4-7 are "ftyp".
                    return h.Length >= 8 && h[4..8].SequenceEqual("ftyp"u8);
                default:
                    return false;
            }
        }
    }
}
